package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct { // 01 SCHED-REC, 16 bytes
	ScAcct  string          // PIC X(4) @0 len=4
	ScPrin  decimal.Decimal // PIC 9(5)V99 @4 len=7
	ScRate  decimal.Decimal // PIC 9(2)V99 @11 len=4
	ScYears int64           // PIC 9(1) @15 len=1
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                   // PIC X len=1 = "N"
var WsBal decimal.Decimal = decimal.Zero     // PIC 9(8)V99 len=10 = 0
var WsYear int64 = 0                         // PIC 99 len=2 = 0
var WsCount int64 = 0                        // PIC 99 len=2 = 0
var WsBalEd string                           // PIC ZZ,ZZZ,ZZ9.99 len=13

var curRec SchedRec
var scanner *bufio.Scanner

func parseDecimalField(field string, scale int32) decimal.Decimal {
	var b strings.Builder
	for i := 0; i < len(field); i++ {
		c := field[i]
		if c >= '0' && c <= '9' {
			b.WriteByte(c)
		} else {
			b.WriteByte('0')
		}
	}
	digits := b.String()
	if digits == "" {
		return decimal.Zero
	}
	d, _ := decimal.NewFromString(digits)
	if scale != 0 {
		d = d.Shift(-scale)
	}
	return d
}

func parseIntField(field string) int64 {
	var b strings.Builder
	for i := 0; i < len(field); i++ {
		c := field[i]
		if c >= '0' && c <= '9' {
			b.WriteByte(c)
		} else {
			b.WriteByte('0')
		}
	}
	digits := b.String()
	if digits == "" {
		return 0
	}
	v, _ := strconv.ParseInt(digits, 10, 64)
	return v
}

func storeBal(d decimal.Decimal) decimal.Decimal {
	mod := decimal.New(1, 8) // 10^8 = 100000000
	if d.IsZero() {
		return d
	}
	return d.Mod(mod)
}

func storeInt(v int64, digits int) int64 {
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	if mod == 0 {
		return v
	}
	return v % mod
}

func FormatBalEd(d decimal.Decimal) string {
	isNeg := d.IsNegative()
	if isNeg {
		d = d.Abs()
	}
	s := d.StringFixed(2)
	parts := strings.SplitN(s, ".", 2)
	intPart := parts[0]
	fracPart := "00"
	if len(parts) == 2 {
		fracPart = parts[1]
		if len(fracPart) < 2 {
			fracPart = fracPart + strings.Repeat("0", 2-len(fracPart))
		} else if len(fracPart) > 2 {
			fracPart = fracPart[:2]
		}
	}
	if len(intPart) > 8 {
		intPart = intPart[len(intPart)-8:]
	} else if len(intPart) < 8 {
		intPart = strings.Repeat("0", 8-len(intPart)) + intPart
	}
	firstNonZero := 8
	for i, ch := range intPart {
		if ch != '0' {
			firstNonZero = i
			break
		}
	}
	digitChars := make([]byte, 8)
	for i := 0; i < 8; i++ {
		ch := intPart[i]
		if i == 7 {
			digitChars[i] = byte(ch)
		} else {
			if i < firstNonZero {
				digitChars[i] = ' '
			} else {
				digitChars[i] = byte(ch)
			}
		}
	}
	out := make([]byte, 13)
	out[0] = digitChars[0]
	out[1] = digitChars[1]
	if firstNonZero > 1 {
		out[2] = ' '
	} else {
		out[2] = ','
	}
	out[3] = digitChars[2]
	out[4] = digitChars[3]
	out[5] = digitChars[4]
	if firstNonZero > 4 {
		out[6] = ' '
	} else {
		out[6] = ','
	}
	out[7] = digitChars[5]
	out[8] = digitChars[6]
	out[9] = digitChars[7]
	out[10] = '.'
	out[11] = fracPart[0]
	out[12] = fracPart[1]

	if isNeg {
		// place minus before first digit if possible
		firstPos := -1
		for i := 0; i < 10; i++ {
			if out[i] >= '0' && out[i] <= '9' {
				firstPos = i
				break
			}
		}
		if firstPos != -1 {
			placed := false
			for i := firstPos - 1; i >= 0; i-- {
				if out[i] == ' ' {
					out[i] = '-'
					placed = true
					break
				}
			}
			if !placed {
				// fallback: overwrite first space if any
				for i := 0; i < firstPos; i++ {
					if out[i] == ' ' {
						out[i] = '-'
						break
					}
				}
			}
		}
	}
	return string(out)
}

// Paragraphs

func ReadPara() {
	if scanner.Scan() {
		line := scanner.Text()
		if len(line) < 16 {
			line = line + strings.Repeat(" ", 16-len(line))
		} else if len(line) > 16 {
			line = line[:16]
		}
		curRec.ScAcct = line[0:4]
		curRec.ScPrin = parseDecimalField(line[4:11], 2)
		curRec.ScRate = parseDecimalField(line[11:15], 2)
		curRec.ScYears = parseIntField(line[15:16])
	} else {
		if err := scanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	WsBal = storeBal(curRec.ScPrin)
	WsYear = storeInt(1, 2)
	for !(WsYear > curRec.ScYears) {
		rateDiv := curRec.ScRate.Shift(-2)
		onePlus := decimal.NewFromInt(1).Add(rateDiv)
		prod := WsBal.Mul(onePlus)
		rounded := prod.Round(2)
		WsBal = storeBal(rounded)
		WsBalEd = FormatBalEd(WsBal)
		yearStr := fmt.Sprintf("%02d", WsYear)
		fmt.Printf("%s Y%s %s\n", curRec.ScAcct, yearStr, WsBalEd)
		WsYear = storeInt(WsYear+1, 2)
	}
	WsBalEd = FormatBalEd(WsBal)
	fmt.Printf("%s FINAL %s\n", curRec.ScAcct, WsBalEd)
	WsCount = storeInt(WsCount+1, 2)
	ReadPara()
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			fmt.Printf("SCHEDULES: %02d\n", WsCount)
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer f.Close()
	scanner = bufio.NewScanner(f)
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	fmt.Printf("SCHEDULES: %02d\n", WsCount)
}

func main() {
	WsEofFlag = "N"
	WsBal = decimal.Zero
	WsYear = 0
	WsCount = 0
	WsBalEd = ""
	MainPara()
}
